import { render, screen, fireEvent } from '@testing-library/react';
import Counter from './UserCode';

test('initial count is 0', () => {
  render(<Counter />);
  expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('0');
});

test('Increment button increases count by 1', () => {
  render(<Counter />);
  fireEvent.click(screen.getByText('Increment'));
  expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('1');
});

test('Decrement button decreases count by 1', () => {
  render(<Counter />);
  fireEvent.click(screen.getByText('Decrement'));
  expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('-1');
});

test('Reset button resets count to 0 after changes', () => {
  render(<Counter />);
  fireEvent.click(screen.getByText('Increment'));
  fireEvent.click(screen.getByText('Increment'));
  fireEvent.click(screen.getByText('Reset'));
  expect(screen.getByRole('heading', { level: 1 }).textContent).toBe('0');
});

